function string(value: unknown, path: string, pattern?: RegExp): string { if (typeof value !== 'string' || (pattern && !pattern.test(value))) fail(path, 'expected valid string'); return value; }
function nullableString(value: unknown, path: string): string | null { return value === null ? null : string(value, path); }
function number(value: unknown, path: string, integer = true): number { if (typeof value !== 'number' || !Number.isFinite(value) || (integer && !Number.isInteger(value))) fail(path, 'expected finite number'); return value; }
function nonnegative(value: unknown, path: string): number { const n = number(value, path); if (n < 0) fail(path, 'expected nonnegative integer'); return n; }
function nullableNumber(value: unknown, path: string): number | null { return value === null ? null : number(value, path); }
